import{_ as i,o as s,c as a,a3 as r,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Basisreports auswählen und verwenden","description":"","frontmatter":{"title":"Basisreports auswählen und verwenden","source_pageid":1611,"source_revision":7189},"headers":[],"relativePath":"reporting/basisreports/basisreports-downloads-themenuebersicht.md","filePath":"reporting/basisreports/basisreports-downloads-themenuebersicht.md"}'),l={name:"reporting/basisreports/basisreports-downloads-themenuebersicht.md"};function u(o,n,h,d,g,p){return s(),a("div",null,[...n[0]||(n[0]=[r('<h1 id="basisreports-auswahlen-und-verwenden" tabindex="-1">Basisreports auswählen und verwenden <a class="header-anchor" href="#basisreports-auswahlen-und-verwenden" aria-label="Permalink to &quot;Basisreports auswählen und verwenden&quot;">​</a></h1><p>Die Basisreportsammlung enthält Vorlagen für häufige Aufgaben. Finden Sie hier den passenden Zugang zu Downloads, Serienbriefen, Leistungsübersichten und Aufnahmebögen.</p><p><a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a></p><h2 id="basisreports-und-downloads" tabindex="-1">Basisreports und Downloads <a class="header-anchor" href="#basisreports-und-downloads" aria-label="Permalink to &quot;Basisreports und Downloads&quot;">​</a></h2><p>Mit der Installation von SchILD-NRW 3 wird eine Basisreportsammlung einmalig im SVWS-Arbeitsverzeichnis hinterlegt. Sie enthält Reports für typische Bedarfe in der Schule und folgt einer konsequenten Designrichtlinie. Die Sammlung ist ein guter Ausgangspunkt, um eigene Varianten eines Reports zu erstellen.</p>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis – Download")]),e("p",null,[e("a",{href:"https://github.com/SVWS-NRW/Schild-NRW-3-Reports/releases",target:"_blank",rel:"noreferrer"},"Laden Sie über diesen Link die neuste Version der Basisreportsammlung auf GitHub herunter.")])],-1),r('<p>Die Basisreportsammlung wird bei der Erstinstallation von SchILD-NRW 3 im SVWS-Arbeitsverzeichnis abgelegt. Sie wird bei Updates nicht automatisch aktualisiert. Im Release-Bereich auf GitHub wächst sie jedoch stetig weiter. Sie können dort jederzeit die neueste Sammlung herunterladen, um Ihre Reports in SchILD-NRW 3 zu ergänzen und auf den aktuellen Stand zu bringen.</p><h2 id="grundlegende-informationen" tabindex="-1">Grundlegende Informationen <a class="header-anchor" href="#grundlegende-informationen" aria-label="Permalink to &quot;Grundlegende Informationen&quot;">​</a></h2><ul><li><a href="/reporting/basisreports/basisreportsammlung-herunterladen-und-aktualisieren.html">Die Basisreportsammlung herunterladen und aktualisieren</a></li></ul><p>Download und Aktualisierung der Reportsammlung</p><ul><li><a href="/reporting/basisreports/basisreportsammlung-ein-ueberblick.html">Die Basisreportsammlung im Überblick</a></li></ul><p>Was ist enthalten und wie wird sie genutzt</p><ul><li><a href="/reporting/basisreports/basisreportsammlung-designrichtlinien.html">Reports übersichtlich und wartbar gestalten</a></li></ul><p>Hinweise für eigenes Layout</p><h2 id="serienbriefe-drucken" tabindex="-1">Serienbriefe drucken <a class="header-anchor" href="#serienbriefe-drucken" aria-label="Permalink to &quot;Serienbriefe drucken&quot;">​</a></h2><ul><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbriefe.html">Serienbriefe einrichten und drucken</a></li></ul><p>Briefkopf, Daten und RTF-Texte verbinden</p><ul><li><a href="/reporting/serienbriefe/basisreportsammlung-einen-serienbrieftext-erstellen-schritt-fuer-schritt.html">Serienbrieftexte erstellen und wiederverwenden</a></li></ul><p>Brieftexte erstellen, speichern und wiederverwenden</p><ul><li><a href="/reporting/serienbriefe/platzhalter.html">Platzhalter für Serienbriefe</a></li></ul><p>Alle Platzhalter übersichtlich präsentiert</p><ul><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-mahnung-gefaehrdete-versetzung.html">Serienbrief zur Mahnung bei gefährdeter Versetzung</a></li></ul><p>Mahnbrief und zugehörige Verarbeitung nachschlagen</p><ul><li><a href="/reporting/serienbriefe/basisreportsammlung-serienbrief-nichtversetzung.html">Serienbriefe zur Nichtversetzung erstellen</a></li></ul><p>Informieren Sie Erziehungsberechtigte</p><h2 id="leistungsubersichten-und-bescheinigungen" tabindex="-1">Leistungsübersichten und Bescheinigungen <a class="header-anchor" href="#leistungsubersichten-und-bescheinigungen" aria-label="Permalink to &quot;Leistungsübersichten und Bescheinigungen&quot;">​</a></h2><ul><li><a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-halbjahr.html">Leistungsübersichten für ein Halbjahr</a></li></ul><p>Für Konferenz mit Teilleistungen und Beamerprojektion</p><ul><li><a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-halbjahr-schuljahr.html">Leistungsübersichten für Halbjahr und Schuljahr</a></li></ul><p>Für Konferenzen mit Teilleistungen</p><ul><li><a href="/reporting/basisreports/basisreportsammlung-leistungsuebersichten-jg-q1-bis-q2.html">Leistungsübersichten für Q1 und Q2</a></li></ul><p>Für Konferenz mit Teilleistungen und Beamerprojektion</p><ul><li><a href="/reporting/serienbriefe/basisreportsammlung-bescheinigungen-des-bilingualen-bildungsgangs.html">Bescheinigungen für den bilingualen Bildungsgang erstellen</a></li></ul><p>Auf englisch und französisch</p><h2 id="aufnahmebogen-als-pdf-und-odt-dateien" tabindex="-1">Aufnahmebögen als PDF- und ODT-Dateien <a class="header-anchor" href="#aufnahmebogen-als-pdf-und-odt-dateien" aria-label="Permalink to &quot;Aufnahmebögen als PDF- und ODT-Dateien&quot;">​</a></h2><ul><li><a href="/reporting/basisreports/basisreportsammlung-aufnahmeboegen.html">Aufnahmebögen verwenden und anpassen</a></li></ul><p>Gebrauchsfertig und anpassbar</p><h2 id="fruhere-anderungen-nachschlagen" tabindex="-1">Frühere Änderungen nachschlagen <a class="header-anchor" href="#fruhere-anderungen-nachschlagen" aria-label="Permalink to &quot;Frühere Änderungen nachschlagen&quot;">​</a></h2><ul><li><a href="/reporting/archiv/basisreportsammlung-versionsgeschichte.html">Versionsgeschichte der Basisreportsammlung</a></li></ul><p>Vor dem Umzug nach GitHub</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Basisreports_%26_Downloads_Themen%C3%BCbersicht" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7189.</p>',36)])])}const m=i(l,[["render",u]]);export{c as __pageData,m as default};
